-- ============================================================================
-- 8) Dijital Ürün Pasaportları (DPP) -- dpp.service.ts#buildPassportData ile
--    BİREBİR aynı JSON şekli, SQL içinde canlı hesaplanıyor (bkz. dosya başı not 4).
-- ============================================================================

INSERT INTO material_passports (id, output_id, passport_data, dpp_compliant, qr_code, pdf_url)
SELECT
  pp.passport_id,
  o.id,
  jsonb_build_object(
    'dpp_version', '1.0',
    'passport_id', pp.passport_id::text,
    'product_id', upper(left(o.id::text, 8)) || '-' || to_char(o.created_at, 'YYYY-MM'),
    'issuer', jsonb_build_object(
      'facility_name', f.name,
      'tax_id', f.tax_id,
      'location', jsonb_build_object(
        'lat', ST_Y(f.location::geometry),
        'lng', ST_X(f.location::geometry),
        'osb', osb.name
      )
    ),
    'material', jsonb_build_object(
      'class', upper(o.material_class::text),
      'description', o.description,
      'composition', o.composition,
      'quantity_kg', o.quantity_kg,
      'hazardous', false
    ),
    'origin', jsonb_build_object(
      'process', NULL,
      'production_date', to_char(o.created_at, 'YYYY-MM-DD'),
      'batch', NULL
    ),
    'traceability', jsonb_build_object(
      'created_at', o.created_at,
      'updated_at', o.created_at,
      'chain_of_custody', '[]'::jsonb
    ),
    'compliance', jsonb_build_object(
      'espr_compliant', (abs(comp_sum.total - 100) <= 0.5),
      'cbam_ready', false,
      'issues', (
        SELECT COALESCE(jsonb_agg(issue), '[]'::jsonb) FROM (VALUES
          (CASE WHEN abs(comp_sum.total - 100) > 0.5 THEN 'composition_sum_invalid' END),
          (CASE WHEN o.material_class IS NULL THEN 'material_class_missing' END),
          (CASE WHEN f.location IS NULL THEN 'issuer_location_missing' END),
          (CASE WHEN o.created_at IS NULL THEN 'production_date_missing' END)
        ) AS t(issue) WHERE issue IS NOT NULL
      ),
      'certifications', '[]'::jsonb
    ),
    'signature', jsonb_build_object('algorithm', 'HMAC-SHA256', 'value', NULL)
  ) AS passport_data,
  (abs(comp_sum.total - 100) <= 0.5 AND o.material_class IS NOT NULL AND f.location IS NOT NULL AND o.created_at IS NOT NULL) AS dpp_compliant,
  NULL,
  NULL
FROM outputs o
JOIN facilities f ON f.id = o.facility_id
LEFT JOIN osbs osb ON osb.id = f.osb_id
JOIN (VALUES
  ('95239a63-266b-4033-8d12-d57ef71b8a46'::uuid, 'ce44195e-3e41-4ecf-a236-f6f3a4753a24'::uuid),
  ('d5fd1c57-88fc-4876-91c0-fbe2b04f2178'::uuid, 'e689c7a4-7e4e-4e4d-a4b5-58069611bac7'::uuid),
  ('62107d64-2a37-4310-a5ab-b035f122cda9'::uuid, '6e7d0e20-383e-4ecd-ab34-470769586c4a'::uuid),
  ('4789a020-8f7f-4a37-92e3-d998ba0b12dd'::uuid, '57679659-e0cc-4131-b386-4fe90c4b026b'::uuid),
  ('b1c158c8-ab2c-4b99-937f-37ad27211a5e'::uuid, '908e36e6-0420-4ac6-badf-b3bab5509070'::uuid),
  ('67c7a6f4-6af2-4c60-aadf-685164cbfe78'::uuid, 'b22337d3-e276-43a3-8a56-d9b225ae3b79'::uuid)
) AS pp(output_id, passport_id) ON pp.output_id = o.id
JOIN LATERAL (
  SELECT COALESCE(sum(value::numeric), 0) AS total
  FROM jsonb_each_text(COALESCE(o.composition, '{}'::jsonb))
) comp_sum ON TRUE
ON CONFLICT (output_id) DO NOTHING;

-- ============================================================================
-- 9) Eşleşmeler (matches) -- match_status durum makinesinin BEŞ durumunu da örnekler.
--    Skor/CO2/CBAM/lojistik SQL içinde CANLI hesaplanıyor -- scoring.service.ts'in
--    (materialScore/qualityScore/environmentalScore/logisticsScore/economicScore/
--    totalScore/cbam/costSaving) formülleriyle birebir aynı, elle hesaplanmış bir
--    sayı YOK. weights_config (aktif versiyon) ve carbon_factors (009_seed.sql'den)
--    canlı okunuyor -- AD2/AD3 sonradan bunları değiştirirse bu satırlar STALE kalır
--    (gerçek sistemde de öyle: rapor üretildiği andaki değerlerle donar, K-'AD3 retroaktif değil').
--
--    match_a  organik çamur      Doku Tekstil  -> Yapı Grup           COMPLETED (S3+S4 mutlu yol)
--    match_b  alüminyum hurda    Gebze Metal   -> Dilovası Alüminyum  ACCEPTED  (tek taraf onayladı)
--    match_c  solvent atığı      Kocaeli Kimya -> Anadolu Kimya       PENDING   (taze aday, dokunulmamış)
--    match_d  PET/PP kırığı      Kemalpaşa     -> Marmara Ambalaj     REJECTED  (A1: kalite yetersiz)
--    match_e  kağıt/karton       Anadolu Kağıt -> Trakya Kağıt        EXPIRED   (A3: 30 gün doldu)
-- ============================================================================

WITH mp(match_id, output_id, input_id, supply_kg, demand_kg, status, created_days_ago,
        accepted_supplier_offset_days, accepted_consumer_offset_days, rejection_category, rejection_text) AS (
  VALUES
    -- supply_kg/demand_kg: eşleşmenin OLUŞTUĞU andaki arz/talep (bkz. bölüm 5'teki not --
    -- match_a'nın output'u artık stock=0, o yüzden burada BAĞIMSIZ sabitler kullanılıyor).
    ('fd82f147-2c81-4b15-bd92-3188b106b15a'::uuid, '95239a63-266b-4033-8d12-d57ef71b8a46'::uuid, '552d9937-c3c8-46b9-97b5-21c858145c8c'::uuid, 800::numeric, 950::numeric, 'completed'::match_status, 10, 9, 8, NULL::varchar, NULL::text),
    ('6e36ad57-f652-4835-a4f1-6767fcfb7198'::uuid, 'd5fd1c57-88fc-4876-91c0-fbe2b04f2178'::uuid, '1d092163-567a-4b8b-94a4-2e5edf6a1b00'::uuid, 12000::numeric, 8000::numeric, 'accepted'::match_status, 3, 2, NULL, NULL, NULL),
    ('dffe0003-ef7a-4132-99a5-1b7fe56d9af5'::uuid, '62107d64-2a37-4310-a5ab-b035f122cda9'::uuid, '58e47423-6367-45d2-b543-0dbdd05458d7'::uuid, 500::numeric, 1500::numeric, 'pending'::match_status, 0, NULL, NULL, NULL, NULL),
    ('ab2ac1a7-c2ea-49fb-887a-2818b8bb11f0'::uuid, '4789a020-8f7f-4a37-92e3-d998ba0b12dd'::uuid, '930406d1-f76a-4327-9713-c55e7e0019e6'::uuid, 3000::numeric, 2000::numeric, 'rejected'::match_status, 15, NULL, NULL, 'quality_insufficient', 'Numune saflık oranı yeterli değil: PET oranı %55, biz %90 üstü bekliyoruz; ayrıca renk bilgisi paylaşılmamış.'),
    ('3c85c6cb-500d-4ebc-b07a-44e9764a5b11'::uuid, 'b1c158c8-ab2c-4b99-937f-37ad27211a5e'::uuid, '454987cd-22d7-4f80-b020-41525cbc9277'::uuid, 4000::numeric, 3500::numeric, 'expired'::match_status, 40, NULL, NULL, NULL, NULL)
),
-- Her satıra kaydın ait olduğu çıktı/girdi/tesis + geriye dönük "created_at" ekleniyor.
base AS (
  SELECT
    mp.*,
    o.material_class, o.composition,
    i.specs,
    f_out.location AS out_location,
    f_in.location AS in_location,
    NOW() - (mp.created_days_ago || ' days')::interval AS created_at
  FROM mp
  JOIN outputs o ON o.id = mp.output_id
  JOIN inputs i ON i.id = mp.input_id
  JOIN facilities f_out ON f_out.id = o.facility_id
  JOIN facilities f_in ON f_in.id = i.facility_id
),
-- Kosinüs benzerliği: yukarıda seed'lenen GERÇEK embedding vektörlerinden okunuyor.
sim AS (
  SELECT b.match_id, 1 - (e_out.vector <=> e_in.vector) AS similarity
  FROM base b
  JOIN embeddings e_out ON e_out.record_id = b.output_id AND e_out.record_type = 'output'
  JOIN embeddings e_in ON e_in.record_id = b.input_id AND e_in.record_type = 'input'
),
-- Miktar oranı + GERÇEK PostGIS mesafesi (rota km).
geo AS (
  SELECT
    b.match_id,
    LEAST(b.supply_kg, b.demand_kg) AS matched_qty,
    LEAST(b.supply_kg, b.demand_kg) / GREATEST(b.supply_kg, b.demand_kg) AS quantity_ratio,
    ST_Distance(b.out_location, b.in_location) / 1000 AS distance_km
  FROM base b
),
-- 009_seed.sql'de zaten seed'lenmiş carbon_factors -- AD3 sonradan günceller/kapatırsa
-- bu satırlar geçmişe dönük SABİT kalır (gerçek sistemdeki "rapor donar" kuralıyla aynı).
carbon AS (
  SELECT
    b.match_id,
    COALESCE(cv.co2_per_kg, 0) AS virgin,
    COALESCE(cs.co2_per_kg, 0) AS secondary
  FROM base b
  LEFT JOIN carbon_factors cv ON cv.material_class = b.material_class AND cv.factor_type = 'virgin'
    AND cv.valid_from <= NOW() AND (cv.valid_to IS NULL OR cv.valid_to > NOW())
  LEFT JOIN carbon_factors cs ON cs.material_class = b.material_class AND cs.factor_type = 'secondary'
    AND cs.valid_from <= NOW() AND (cs.valid_to IS NULL OR cs.valid_to > NOW())
),
-- qualityScore: inputs.specs anahtarlarının outputs.composition tarafından karşılanma oranı.
quality_calc AS (
  SELECT
    b.match_id,
    (SELECT count(*) FROM jsonb_object_keys(COALESCE(b.specs, '{}'::jsonb))) AS criteria_count,
    (SELECT count(*) FROM jsonb_object_keys(COALESCE(b.specs, '{}'::jsonb)) k
       WHERE COALESCE(b.composition, '{}'::jsonb) ? k) AS satisfied_count
  FROM base b
),
-- scoring.service.ts#MATERIAL_PRICES_EUR_PER_KG ile birebir aynı yer tutucu tablo.
price AS (
  SELECT
    b.match_id,
    CASE b.material_class::text
      WHEN 'metal' THEN 2.5 WHEN 'plastic' THEN 1.8 WHEN 'organic' THEN 0.4 WHEN 'chemical' THEN 3.0
      WHEN 'textile' THEN 2.2 WHEN 'glass' THEN 0.3 WHEN 'paper' THEN 0.6 ELSE 1.0 END AS virgin_price,
    CASE b.material_class::text
      WHEN 'metal' THEN 1.2 WHEN 'plastic' THEN 0.7 WHEN 'organic' THEN 0.1 WHEN 'chemical' THEN 1.5
      WHEN 'textile' THEN 0.9 WHEN 'glass' THEN 0.12 WHEN 'paper' THEN 0.2 ELSE 0.4 END AS secondary_price
  FROM base b
),
-- Beş faktörün kendisi + CBAM/maliyet hesabının ara değerleri (scoring.service.ts ile birebir).
scores AS (
  SELECT
    b.match_id,
    GREATEST(0, LEAST(100,
      ((sim.similarity - 0.6) / 0.4) * 100 - (CASE WHEN geo.quantity_ratio < 0.2 THEN 30 ELSE 0 END)
    )) AS material,
    CASE WHEN qc.criteria_count = 0 THEN 70 ELSE (qc.satisfied_count::numeric / qc.criteria_count) * 100 END AS quality,
    CASE WHEN carbon.virgin <= 0 THEN 0 ELSE ((carbon.virgin - carbon.secondary) / carbon.virgin) * 100 END AS environmental,
    GREATEST(0, 100 - (geo.distance_km / 250) * 100) AS logistics,
    (price.virgin_price - price.secondary_price) * geo.matched_qty AS gross_saving,
    geo.distance_km * geo.matched_qty * 0.002 AS transport,
    geo.matched_qty,
    (carbon.virgin - carbon.secondary) * geo.matched_qty AS co2_saved_kg
  FROM base b
  JOIN sim ON sim.match_id = b.match_id
  JOIN geo ON geo.match_id = b.match_id
  JOIN carbon ON carbon.match_id = b.match_id
  JOIN quality_calc qc ON qc.match_id = b.match_id
  JOIN price ON price.match_id = b.match_id
),
final AS (
  SELECT
    s.match_id, s.material, s.quality, s.environmental, s.logistics,
    CASE WHEN s.gross_saving <= 0 THEN 0
      ELSE LEAST(100, GREATEST(0, ((s.gross_saving - s.transport) / s.gross_saving) * 100))
      END AS economic,
    s.matched_qty,
    s.co2_saved_kg,
    (s.co2_saved_kg / 1000) * 85 AS cbam_saving_eur,  -- cbam.carbon_price_eur_per_ton varsayılanı (system_config'te yok, kod 85 döner)
    GREATEST(0, s.gross_saving - s.transport) AS cost_saving_eur
  FROM scores s
)
INSERT INTO matches (
  id, output_id, input_id, total_score, breakdown, status, demand_qty,
  co2_saved, cost_saving, cbam_impact, rejection_reason_category, rejection_reason_text,
  accepted_by_supplier_at, accepted_by_consumer_at, expires_at, created_at
)
SELECT
  b.match_id, b.output_id, b.input_id,
  ROUND(LEAST(100, GREATEST(0,
    f.material * w.material + f.quality * w.quality + f.environmental * w.environmental
    + f.logistics * w.logistics + f.economic * w.economic
  )))::int AS total_score,
  jsonb_build_object(
    'material', ROUND(f.material), 'quality', ROUND(f.quality), 'environmental', ROUND(f.environmental),
    'logistics', ROUND(f.logistics), 'economic', ROUND(f.economic)
  ) AS breakdown,
  b.status,
  f.matched_qty,
  f.co2_saved_kg,
  f.cost_saving_eur,
  f.cbam_saving_eur,
  b.rejection_category,
  b.rejection_text,
  CASE WHEN b.accepted_supplier_offset_days IS NULL THEN NULL
       ELSE b.created_at + (b.accepted_supplier_offset_days || ' days')::interval END,
  CASE WHEN b.accepted_consumer_offset_days IS NULL THEN NULL
       ELSE b.created_at + (b.accepted_consumer_offset_days || ' days')::interval END,
  b.created_at + INTERVAL '30 days' AS expires_at,
  b.created_at
FROM base b
JOIN final f ON f.match_id = b.match_id
CROSS JOIN weights_config w
WHERE w.active = TRUE
ON CONFLICT (id) DO NOTHING;

